#include <bits/stdc++.h>
using namespace std;

static constexpr long long MOD = 998244353;

template<int N>
struct Matrix {
    long long a[N][N]{};

    static Matrix identity() {
        Matrix r;
        for (int i = 0; i < N; ++i) r.a[i][i] = 1;
        return r;
    }

    Matrix operator*(const Matrix& other) const {
        Matrix r;
        for (int i = 0; i < N; ++i) {
            for (int k = 0; k < N; ++k) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < N; ++j) {
                    if (other.a[k][j] == 0) continue;
                    r.a[i][j] = (r.a[i][j] +
                        a[i][k] * other.a[k][j]) % MOD;
                }
            }
        }
        return r;
    }
};

template<int N>
Matrix<N> matrixPower(Matrix<N> base, long long exponent) {
    Matrix<N> result = Matrix<N>::identity();
    while (exponent > 0) {
        if (exponent & 1) result = result * base;
        base = base * base;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    Matrix<16> transition;

    auto addNonMonomerTransitions = [&](int occupancy, int markers,
                                        int nextOccupancy) {
        int from = occupancy * 4 + markers;
        for (int nextMarkers = 0; nextMarkers < 4; ++nextMarkers) {
            if ((nextMarkers | markers) == nextMarkers) {
                int to = nextOccupancy * 4 + nextMarkers;
                transition.a[from][to]++;
                if (transition.a[from][to] == MOD)
                    transition.a[from][to] = 0;
            }
        }
    };

    for (int occupancy = 0; occupancy < 4; ++occupancy) {
        for (int markers = 0; markers < 4; ++markers) {
            if (occupancy & 1) {
                addNonMonomerTransitions(
                    occupancy, markers, occupancy >> 1
                );
            } else {
                if (markers == 3) {
                    int from = occupancy * 4 + markers;
                    int nextOccupancy = occupancy >> 1;
                    int to = nextOccupancy * 4;
                    transition.a[from][to]++;
                }

                if ((occupancy & 2) == 0) {
                    int nextOccupancy = (occupancy | 2) >> 1;
                    addNonMonomerTransitions(
                        occupancy, markers, nextOccupancy
                    );
                }

                int nextOccupancy = (occupancy >> 1) | 2;
                addNonMonomerTransitions(
                    occupancy, markers, nextOccupancy
                );
            }
        }
    }

    Matrix<4> noDiameterTransition;

    for (int occupancy = 0; occupancy < 4; ++occupancy) {
        if (occupancy & 1) {
            noDiameterTransition.a[occupancy][occupancy >> 1]++;
        } else {
            if ((occupancy & 2) == 0) {
                int nextOccupancy = (occupancy | 2) >> 1;
                noDiameterTransition.a[occupancy][nextOccupancy]++;
            }

            int nextOccupancy = (occupancy >> 1) | 2;
            noDiameterTransition.a[occupancy][nextOccupancy]++;
        }
    }

    auto totalMatrix = matrixPower(transition, n);
    auto noDiameterMatrix = matrixPower(noDiameterTransition, n);

    long long total = 0;
    for (int i = 0; i < 16; ++i) {
        total = (total + totalMatrix.a[i][i]) % MOD;
    }

    long long noDiameter = 0;
    for (int i = 0; i < 4; ++i) {
        noDiameter = (noDiameter + noDiameterMatrix.a[i][i]) % MOD;
    }

    total = (total - 4 * noDiameter) % MOD;
    if (total < 0) total += MOD;

    cout << total << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 998244353;

using Poly = vector<int64>;

void trim(Poly& a) {
    while (a.size() > 1 && a.back() == 0) a.pop_back();
}

Poly addPoly(const Poly& a, const Poly& b) {
    Poly c(max(a.size(), b.size()), 0);
    for (size_t i = 0; i < a.size(); ++i) c[i] = a[i];
    for (size_t i = 0; i < b.size(); ++i) {
        c[i] += b[i];
        if (c[i] >= MOD) c[i] -= MOD;
    }
    trim(c);
    return c;
}

Poly subPoly(const Poly& a, const Poly& b) {
    Poly c(max(a.size(), b.size()), 0);
    for (size_t i = 0; i < a.size(); ++i) c[i] = a[i];
    for (size_t i = 0; i < b.size(); ++i) {
        c[i] -= b[i];
        if (c[i] < 0) c[i] += MOD;
    }
    trim(c);
    return c;
}

Poly mulPoly(const Poly& a, const Poly& b) {
    Poly c(a.size() + b.size() - 1, 0);
    for (size_t i = 0; i < a.size(); ++i) {
        for (size_t j = 0; j < b.size(); ++j) {
            c[i + j] = (c[i + j] + a[i] * b[j]) % MOD;
        }
    }
    trim(c);
    return c;
}

Poly scalePoly(Poly a, int64 k) {
    k %= MOD;
    if (k < 0) k += MOD;
    for (auto& x : a) x = x * k % MOD;
    trim(a);
    return a;
}

Poly shiftPoly(const Poly& a, int k) {
    Poly b(k, 0);
    b.insert(b.end(), a.begin(), a.end());
    trim(b);
    return b;
}

Poly derivative(const Poly& a) {
    if (a.size() <= 1) return {0};
    Poly b(a.size() - 1);
    for (size_t i = 1; i < a.size(); ++i) {
        b[i - 1] = a[i] * static_cast<int64>(i) % MOD;
    }
    trim(b);
    return b;
}

int64 logDerivativeCoefficient(const Poly& p, int k) {
    vector<int64> r(k + 1, 0);
    int d = static_cast<int>(p.size()) - 1;

    for (int j = 0; j <= k; ++j) {
        int64 value = 0;
        if (j + 1 <= d) {
            value = static_cast<int64>(j + 1) * p[j + 1] % MOD;
        }

        for (int i = 1; i <= min(j, d); ++i) {
            value = (value - p[i] * r[j - i]) % MOD;
        }

        if (value < 0) value += MOD;
        r[j] = value;
    }

    return r[k];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    Poly H = {1, 0, MOD - 1, 0, MOD - 1};
    Poly Hp = derivative(H);
    Poly Hpp = derivative(Hp);

    Poly NF = mulPoly(H, H);
    Poly NDF = scalePoly(shiftPoly(mulPoly(Hp, H), 1), -1);

    Poly inside = addPoly(Hp, shiftPoly(Hpp, 1));
    Poly term1 = scalePoly(shiftPoly(mulPoly(inside, H), 1), -1);
    Poly term2 = scalePoly(shiftPoly(mulPoly(Hp, Hp), 2), 2);
    Poly ND2 = addPoly(term1, term2);

    Poly N0 = ND2;
    Poly N1 = shiftPoly(
        addPoly(addPoly(ND2, scalePoly(NDF, 2)), NF), 1
    );
    Poly N2 = shiftPoly(
        addPoly(addPoly(ND2, scalePoly(NDF, 4)), scalePoly(NF, 4)), 2
    );

    Poly H2 = mulPoly(H, H);
    Poly H3 = mulPoly(H2, H);

    Poly B0 = subPoly(H3, shiftPoly(N0, 1));
    Poly B2 = subPoly(H3, shiftPoly(N2, 1));

    Poly numerator = subPoly(
        mulPoly(B0, B2),
        shiftPoly(mulPoly(N1, N1), 2)
    );

    int64 rH = logDerivativeCoefficient(H, n - 1);
    int64 rNum = logDerivativeCoefficient(numerator, n - 1);

    int64 answer = (6 * rH - rNum) % MOD;
    if (answer < 0) answer += MOD;

    cout << answer << '\n';
    return 0;
}

