int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long A[3][3] = {
        {1, 0, 0},
        {1, 1, 0},
        {1, 2, 1}
    };

    long long B[3][3] = {
        {0, 0, 1},
        {0, 0, 0},
        {0, 0, 0}
    };

    Matrix weighted(12);
    Matrix unweighted(4);

    auto addWeighted = [&](int from, int to, long long label[3][3]) {
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                int x = from * 3 + i;
                int y = to * 3 + j;
                weighted.a[x][y] += label[i][j];
                if (weighted.a[x][y] >= MOD) weighted.a[x][y] -= MOD;
            }
        }
    };

    auto addUnweighted = [&](int from, int to) {
        unweighted.a[from][to]++;
        if (unweighted.a[from][to] >= MOD) unweighted.a[from][to] -= MOD;
    };

    for (int state = 0; state < 4; ++state) {
        if (state & 1) {
            int nextState = state >> 1;
            addWeighted(state, nextState, A);
            addUnweighted(state, nextState);
        } else {
            int nextState = state >> 1;
            addWeighted(state, nextState, B);

            if ((state & 2) == 0) {
                int dimerOne = (state >> 1) | 1;
                addWeighted(state, dimerOne, A);
                addUnweighted(state, dimerOne);
            }

            int dimerTwo = (state >> 1) | 2;
            addWeighted(state, dimerTwo, A);
            addUnweighted(state, dimerTwo);
        }
    }

    Matrix weightedPower = power(weighted, n);
    Matrix unweightedPower = power(unweighted, n);

    long long answer = 0;
    for (int i = 0; i < 12; ++i) {
        answer += weightedPower.a[i][i];
        if (answer >= MOD) answer -= MOD;
    }

    long long noDiameter = 0;
    for (int i = 0; i < 4; ++i) {
        noDiameter += unweightedPower.a[i][i];
        if (noDiameter >= MOD) noDiameter -= MOD;
    }

    answer = (answer - 3 * noDiameter) % MOD;
    if (answer < 0) answer += MOD;

    cout << answer << '\n';
    return 0;
}

