                int u = from * 3 + x;
                int v = to * 3 + y;
                transfer.a[u][v] =
                    (transfer.a[u][v] + decoration.a[x][y]) % MOD;
            }
        }
        if (isNonDiameter) {
            noDiameterTransfer.a[from][to]++;
            if (noDiameterTransfer.a[from][to] == MOD)
                noDiameterTransfer.a[from][to] = 0;
        }
    };

    for (int state = 0; state < 4; ++state) {
        if (state & 1) {
            int nextState = state >> 1;
            addTransition(state, nextState, nonMonomer, true);
