    int n;
    cin >> n;

    Matrix T0(4), T1(4);

    for (int mask = 0; mask < 4; ++mask) {
        if (mask & 1) {
            int nextMask = mask >> 1;
            T0.a[mask][nextMask]++;
        } else {
            int shifted = mask >> 1;

            T1.a[mask][shifted]++;

            if ((mask & 2) == 0) {
                T0.a[mask][shifted | 1]++;
            }

            T0.a[mask][shifted | 2]++;
        }
    }

    Matrix zeroAutomaton(3);
    zeroAutomaton.a[0][0] = 1;
    zeroAutomaton.a[0][1] = 2;
    zeroAutomaton.a[0][2] = 1;
    zeroAutomaton.a[1][1] = 1;
    zeroAutomaton.a[1][2] = 1;
